import{_ as a,H as e,f as t,i as r}from"./chunks/framework.Cvt1eIE0.js";const I=JSON.parse('{"title":"PIGLIN KING 第四巻 ささやかな日常と小さないたずら","description":"","frontmatter":{"title":"PIGLIN KING 第四巻 ささやかな日常と小さないたずら","outline":"deep"},"headers":[],"relativePath":"story/4-1.md","filePath":"story/4-1.md"}'),o={name:"story/4-1.md"};function i(n,p,s,l,d,_){return e(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="piglin-king" tabindex="-1">PIGLIN KING <a class="header-anchor" href="#piglin-king" aria-label="Permalink to &quot;PIGLIN KING&quot;">​</a></h1><h2 id="第四巻-ささやかな日常と小さないたずら" tabindex="-1">第四巻 ささやかな日常と小さないたずら <a class="header-anchor" href="#第四巻-ささやかな日常と小さないたずら" aria-label="Permalink to &quot;第四巻 ささやかな日常と小さないたずら&quot;">​</a></h2><hr><h1 id="第一章-庭園でのお茶会" tabindex="-1">第一章 庭園でのお茶会 <a class="header-anchor" href="#第一章-庭園でのお茶会" aria-label="Permalink to &quot;第一章 庭園でのお茶会&quot;">​</a></h1><p>王国歴十四年。</p><p>エンダードラゴン戦争から、半年。</p><p>ネザーに季節はない。</p><p>それでも、世界には、確かに「変わった」と呼べる何かがあった。</p><p>戦のない日々が積み重なるにつれ、人々の表情から、強張りが抜けていった。それは、まるで長く握り続けていた拳が、ようやくほどけるような変化だった。</p><p>王都 GOLDEN BASTION。</p><p>王宮の庭園では、ネザーには似つかわしくないほど、色とりどりの花が咲き誇っていた。</p><p>グロウベリーの蔓が石垣を這い、淡い光の粒を実らせていた。風のないはずのネザーで、それでも花弁だけが、わずかに揺れている気がした。小鳥――いや、正確には小鳥に似た何か――のさえずりが、噴き出す光のあいだを縫って響いていた。</p><p>平和とは、こういう音のことを言うのかもしれない。</p><p>「平和ってのは。」</p><p>「いいもんだなぁ。」</p><p>スターリンは椅子に深く腰掛けながら、目の前に積まれた山のようなケーキを、まるで遺跡の罠でも見るような真剣な目で見つめていた。違うのは、彼が今、攻略すべき相手を心の底から愛していることだった。</p><p>「君はさっきから食べてばかりだ。」</p><p>ピックバーグは紅茶を一口含み、苦笑した。眼鏡の奥の目は、相変わらず何かを観察し続けていた。今日に限って言えば、観察対象はスターリンの食欲という、いたって平和な研究テーマだった。</p><p>その向かいで。</p><p>KING PIGLIN I。</p><p>Aurex Goldtusk。</p><p>黄金王は、頬に風を感じるように、ただ静かに空を見上げていた。</p><p>「静かだね。」</p><p>「昔じゃ、考えられない。」</p><p>「そうだな。」</p><p>スターリンも、ケーキを頬張りながら頷いた。</p><p>「昔は毎日、誰かに追いかけられてたからな！」</p><p>三人は、声を揃えて笑った。</p><p>戦争。</p><p>旅。</p><p>建国。</p><p>数え切れないほどの出来事を、共に乗り越えてきた。失ったものも、得たものも、数えきれないほどあった。</p><p>それでも。</p><p>こうして三人で笑い合う時間だけは、何一つ変わらなかった。</p><p>あの路地裏で初めて手を握った日から、何年が過ぎても。あの炎の夜から、何度季節のないネザーの時が流れても。変わらないものが、確かにここにあった。</p><hr><p>「失礼します。」</p><p>若い侍女たちが、お茶を運んできた。湯気が、淡い橙色の光の中で、ゆっくりと立ち上っていた。</p><p>「本日の茶葉は、王立農園産でございます。」</p><p>「ありがとうございます。」</p><p>オーレックスは微笑んだ。</p><p>王立農園――かつて、橋の落ちた村で、子供たちが泣いて喜んだあの土地の、今の姿だった。あの時の子供たちは、今、茶葉を育てる側に立っているのかもしれない。そう思うと、湯気の向こうに、小さな歳月が見える気がした。</p><p>すると。</p><p>「陛下ー！」</p><p>庭園の入口から、子供たちが、わらわらと走ってきた。</p><p>「一緒に遊んでー！」</p><p>「かくれんぼしよう！」</p><p>「鬼ごっこ！」</p><p>それぞれが、てんでに違う遊びを叫ぶものだから、まるで小さな嵐が庭園に押し寄せたようだった。</p><p>「おお！」</p><p>スターリンが、真っ先に立ち上がる。</p><p>「俺も混ぜろ！」</p><p>「なんで君が行くんだ。」</p><p>ピックバーグが呆れる。</p><p>「はっはっは！」</p><p>「子供は元気が一番だ！」</p><p>大斧を振るう将軍が、子供たちに追われて庭園を駆け回る光景は、誰がどう見ても、奇妙だった。しかし、誰もそれを止めなかった。むしろ、その奇妙さこそが、今の平和を、誰よりも雄弁に語っていた。</p><p>しかし。</p><p>その喧騒の中、一人の小さな女の子が、そっとオーレックスの服を引っ張った。</p><p>「王さま。」</p><p>「どうしたの？」</p><p>オーレックスは膝を折り、女の子の高さに目線を合わせた。</p><p>「えっとね。」</p><p>少女は、何かを決意したように、深く息を吸った。</p><p>「いつもありがとう！」</p><p>そう言って、花を一輪、差し出した。グロウベリーの蔓から摘んだのだろう。小さな手の中で、花弁が淡く光っていた。</p><p>「これ。」</p><p>「プレゼント！」</p><p>「……。」</p><p>オーレックスは、目を丸くした。</p><p>そして、優しく受け取った。</p><p>「ありがとう。」</p><p>少女は、嬉しそうに笑う。</p><p>「えへへ！」</p><p>その光が――小さな花の光なのか、少女の笑顔の光なのか、もう分からなかった――胸の奥に、静かに沈んでいくのを、オーレックスは感じた。</p><p>鍛冶屋の槌の音を聞くたびに、父の手を思い出す。</p><p>それと同じように、これからは。</p><p>誰かが無邪気に笑う、その瞬間を見るたびに、この花を思い出すのかもしれない。</p><p>その様子を見て、スターリンはニヤニヤしていた。</p><p>「おいおい。」</p><p>「陛下、泣くなよ？」</p><p>「泣いてないよ。」</p><p>「目から水出てるぞ。」</p><p>「泣いてないって！」</p><p>三人は、また笑った。</p><p>平和。</p><p>それは、戦争に勝つことではない。</p><p>誰かが笑顔で、「ありがとう」と言える世界。</p><p>それこそが、オーレックスが、剣を振るうたびに、橋を架けるたびに、守りたかったものだった。手にした冠が軽かったのも、きっと、この程度のことのためだったのだと、今ならそう思える。</p><hr><p>夕暮れ。</p><p>庭園には、オレンジ色の光が差し込んでいた。溶岩の赤とは違う、もっと柔らかな色だった。子供たちの影が、長く伸びて、石畳の上で重なり合っていた。</p><p>「さて。」</p><p>スターリンが立ち上がる。伸びをすると、骨の音が小さく鳴った。</p><p>「次は何する？」</p><p>「仕事。」</p><p>ピックバーグが即答する。</p><p>「えぇー。」</p><p>「今日は休みじゃなかったのか？」</p><p>「君だけだよ。」</p><p>「休みだと思ってるの。」</p><p>そんな、いつもの軽口を交わしていると。</p><p>親衛隊の若い兵士が、駆け寄ってきた。鎧の音が、慌てた足音に合わせて鳴った。</p><p>「陛下！」</p><p>「王都東地区の警備報告です！」</p><p>「あ、ありがとう。」</p><p>「ご苦労さま。」</p><p>オーレックスは、紙を受け取りながら、にこやかに頷いた。</p><p>兵士は、緊張した顔で敬礼した。</p><p>「は、はい！」</p><p>その背中が小さくなっていくのを見送りながら、スターリンの目が、何かを思いついた子供のように、すうっと光った。</p><p>「なあ。」</p><p>「面白いこと思いついた。」</p><p>「嫌な予感しかしない。」</p><p>ピックバーグは、即座に顔をしかめた。長年の付き合いが、こういう時だけは正確に働く。</p><p>「へへへ。」</p><p>スターリンは、肉汁のついた口元を拭いながら、にやりと笑った。</p><p>「明日。」</p><p>「王様と兵士を入れ替えてみねぇか？」</p><p>「……は？」</p><p>オーレックスは固まった。</p><p>「君は何を言ってるんだ。」</p><p>ピックバーグも呆れた。</p><p>しかし。</p><p>スターリンの目は、悪戯を思いついた子供のように、いつまでも輝いていた。</p><p>その奥には、もう一つの思いがあった。</p><p>誰よりもオーレックスのそばで戦ってきた友として、彼は知っていた。</p><p>王という冠が、どれほど重いものか。</p><p>だから、たまには、その冠を下ろした時間が必要なのではないか――そんな、らしくない優しさが、その悪戯心の裏側にあった。</p><p>もちろん、本人がそれを口にすることは、絶対になかった。</p><p>そして。</p><p>この思いつきが、思いもよらない一日と、運命の出会いへと繋がっていくことを、まだ誰も知らなかった。</p>',132)])])}const c=a(o,[["render",i]]);export{I as __pageData,c as default};
